/* ============================================================
   MAPA GOPIA — archivo propio del Mapa
   ------------------------------------------------------------
   Este archivo (mapa.js) contiene TODO el Mapa: sus datos
   (MAPA_*), su código y sus estilos. Se carga desde index.html.
   Regla de trabajo:
     - El Mapa se modifica SOLO en mapa.js.
     - La agenda se modifica SOLO en index.html.
   Usa funciones de la agenda (sb, escapeHtml, renderRoot, seccion),
   que se resuelven cuando se las llama.
   ============================================================ */

/* ----- Estilos del Mapa ----- */
(function(){
  const st = document.createElement("style");
  st.id = "estilos-mapa";
  st.textContent = `
  /* ---- Mapa GOPIA ---- */
  .breadcrumb{display:flex; gap:6px; align-items:center; font-size:12px; color:var(--ink-soft); margin-bottom:16px; flex-wrap:wrap;}
  .breadcrumb button{font-family:inherit; font-size:12px; color:var(--accent); background:none; border:none; cursor:pointer; font-weight:600; padding:0;}
  .breadcrumb span{color:var(--line);}
  .grid-mapa{display:grid; grid-template-columns:1fr 1fr; gap:10px;}
  @media (max-width:560px){ .grid-mapa{grid-template-columns:1fr;} }
  .card{background:#fff; border:1px solid var(--line); border-radius:10px; padding:14px 16px; text-align:left; cursor:pointer; font-family:inherit; width:100%;}
  .card:hover{border-color:var(--accent);}
  .card-title{font-size:14px; font-weight:700; margin:0 0 4px;}
  .card-sub{font-size:12px; color:var(--ink-soft); margin:0;}
  .root-card{background:var(--accent); color:#fff; border:none; border-radius:12px; padding:20px; margin-bottom:14px; cursor:pointer; text-align:left; width:100%;}
  .root-card .card-title{color:#fff; font-size:17px;}
  .root-card .card-sub{color:#DCEBE8;}
  .report-btn{display:flex; align-items:center; gap:8px; background:#fff; border:1.5px solid var(--accent); color:var(--accent); border-radius:10px; padding:12px 16px; cursor:pointer; font-family:inherit; font-size:13px; font-weight:700; width:100%; margin-bottom:18px;}
  .report-btn:hover{background:var(--accent-soft);}
  .section-label{font-size:11px; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:var(--ink-soft); margin:20px 0 8px;}
  .brief{font-size:13.5px; line-height:1.55; margin:0 0 12px; color:var(--ink);}
  .gestion-box{background:var(--accent-soft); border-radius:8px; padding:10px 12px; font-size:12.5px; color:var(--accent); line-height:1.5; margin-bottom:16px;}
  .gestion-box b{display:block; font-size:10.5px; text-transform:uppercase; letter-spacing:.04em; margin-bottom:3px;}
  .icon-row{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:8px;}
  .icon-chip{display:inline-flex; align-items:center; gap:5px; background:#fff; border:1px solid var(--line); border-radius:20px; padding:6px 12px; font-size:12px; font-weight:600; color:var(--ink); cursor:pointer; font-family:inherit;}
  .icon-chip:hover{border-color:var(--accent); color:var(--accent);}
  .icon-chip.open{background:var(--accent); border-color:var(--accent); color:#fff;}
  .gestion-detail{font-size:12.5px; color:var(--ink-soft); line-height:1.5; background:#fff; border:1px solid var(--line); border-radius:8px; padding:10px 12px; margin:-2px 0 10px;}
  .list-item{background:#fff; border:1px solid var(--line); border-radius:10px; padding:12px 14px; margin-bottom:8px; cursor:pointer;}
  .list-item:hover{border-color:var(--accent);}
  .list-item .nombre{font-size:13.5px; font-weight:700; margin:0 0 3px;}
  .list-item .meta{font-size:11.5px; color:var(--ink-soft);}
  .badge{font-size:10px; font-weight:700; padding:2px 7px; border-radius:5px; text-transform:uppercase;}
  .badge-ok{background:var(--accent-soft); color:var(--accent);}
  .badge-falta{background:#FAE7E7; color:#8A2E2E;}
  .team-item{display:flex; justify-content:space-between; align-items:flex-start; gap:10px; padding:10px 0; border-bottom:1px solid var(--line);}
  .team-item:last-child{border-bottom:none;}
  .team-name{font-size:13.5px; font-weight:700; margin:0;}
  .team-role{font-size:11px; color:var(--accent); font-weight:600; margin:1px 0 3px;}
  .team-resp{font-size:12.5px; color:var(--ink-soft); margin:0; max-width:420px;}
  .status{font-size:12px; color:var(--ink-soft); margin:10px 0;}
  .falta{font-size:11.5px; color:#8A2E2E; font-style:italic;}

  /* ---- Mapa GOPIA: cuadro sinóptico ---- */
  .sinoptico{list-style:none; margin:0; padding:0;}
  .nivel1 > li{position:relative; margin-bottom:28px;}
  .sinoptico .rama{list-style:none; margin:0; padding:0 0 0 32px; position:relative;}
  .sinoptico .rama::before{content:""; position:absolute; left:11px; top:0; bottom:22px; width:0; border-left:3px solid #B8B6A8;}
  .sinoptico .rama > li{position:relative; padding-left:20px; margin-bottom:18px;}
  .sinoptico .rama > li::before{content:""; position:absolute; left:0; top:15px; width:18px; height:0; border-top:3px solid #B8B6A8;}
  .titulo-l1{display:inline-block; font-size:17px; font-weight:800; color:#fff; background:var(--accent); padding:7px 16px; border-radius:8px; margin-bottom:10px;}
  .titulo-l1.orbital-sin{background:#993C1D;}
  .titulo-l2{display:inline-block; font-size:14.5px; font-weight:800; color:var(--accent); background:var(--accent-soft); padding:5px 13px; border-radius:7px; margin-bottom:8px;}
  .titulo-l2.orbital-sin{color:#993C1D; background:#FAECE7;}
  .titulo-l3{display:block; font-size:12.5px; font-weight:700; color:var(--ink); text-transform:uppercase; letter-spacing:.03em; margin-bottom:5px;}
  .sinoptico .contenido{padding:0 0 6px 2px; font-size:13px; line-height:1.6; color:var(--ink-soft); max-width:640px;}
  .sinoptico .contenido p{margin:0 0 9px;}
  .sinoptico .contenido b{color:var(--ink);}
  .team-grid-sin{display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-top:6px;}
  @media (max-width:560px){ .team-grid-sin{grid-template-columns:1fr;} }
  .team-item-sin{background:#fff; border:1px solid var(--line); border-radius:8px; padding:10px 12px;}
  .team-item-sin b{display:block; font-size:13px;}
  .rol-sin{font-size:11.5px; color:var(--accent); font-weight:700;}
  .org-line-sin{font-size:12.5px;}
  `;
  document.head.appendChild(st);
})();

/* ===================== Mapa GOPIA (navegador) ===================== */
const MAPA_TEAM = [{"nombre": "Paula Seminare", "rol": "Gerenta Operativa", "resp": "Conduce la Gerencia Operativa GOPIA."}, {"nombre": "Danilo Dignani", "rol": "Abogado", "resp": "Responsabilidad específica todavía no detallada."}, {"nombre": "Santiago Sandoná", "rol": "Asistente administrativo", "resp": "Gestión administrativa general."}, {"nombre": "Adriana Zapata", "rol": "RAP (Responsable Administrativa Presentismo)", "resp": "Todo lo referido a RRHH."}, {"nombre": "Guadalupe Coll", "rol": "RAP (Responsable Administrativa Presentismo)", "resp": "Todo lo referido a RRHH, además del seguimiento de la contratación de micros, pedidos de comida para los programas y solicitudes de piezas de comunicaciones."}, {"nombre": "Ana Prado Morello", "rol": "Asistente administrativa", "resp": "Gestión administrativa general."}];
const MAPA_PROGRAMAS = {"adolescencias": {"nombre": "Programa Adolescencias", "brief": "El Programa Adolescencia es una iniciativa pensada para estimular las potencialidades y la capacidad creadora de los adolescentes a través de la expresión artística, del acceso a las nuevas tecnologías de información y comunicación como herramienta de integración social, y de la práctica de actividades físicas y deportivas orientadas al desarrollo de la personalidad, el trabajo en equipo y el cuidado de la salud.<br/><br/>Está destinado a adolescentes entre 13 y 18 años que integran hogares en situación de vulnerabilidad social en la Ciudad de Buenos Aires. Se desarrolla a partir de dos ejes fundamentales: los talleres culturales, deportivos y de ciencia y tecnología, y el acompañamiento profesional de los y las adolescentes.", "tiene_organizaciones": true, "gestion": "El programa trabaja de forma integrada con organizaciones sociales territoriales. Esta dinámica funciona en el marco de convenios celebrados que definen los alcances de cada institución, generando espacios de contención, brindando contenidos específicos, acompañamiento y estímulo a la participación.<br/><br/>Cada taller se desarrolla anualmente y es dictado por una tallerista especializada, asistida por una operadora social, quien trabaja en contacto directo y cotidiano con las y los adolescentes, acompaña procesos, sostiene el vínculo y actúa como puente entre la persona, su entorno y las instituciones. Su rol se define por la tarea territorial y de acompañamiento. Tanto la tallerista como la operadora social integran el Programa, pero pertenecen formalmente a la organización conveniada, no a la planta del equipo técnico de la Gerencia.<br/><br/>El taller está diseñado para que las adolescencias que lo transitan cuenten con un espacio de contención socioeducativa y de desarrollo a través del arte, el deporte, la música y las ciencias y tecnologías.<br/><br/>El equipo técnico del Programa se organiza en tres niveles: la Coordinadora del Programa, la Sub Coordinación (cinco personas, cada una a cargo de un equipo) y los equipos territoriales que de ellas dependen. El detalle completo está en Gestiones propias — Sistema de control y Equipo — Sub Coordinaciones.<br/><br/>La Coordinadora del Programa, Patricia González Chans, es responsable de la coordinación de los equipos técnicos y del monitoreo de la generación y disponibilidad de los recursos necesarios para el adecuado funcionamiento del equipo y el desarrollo del Programa.", "diagnostico": "Cierre 2026 (Presentación Desafío 2027): 11.600 adolescentes inscriptos, 7.000 cupos disponibles y 4.600 de demanda no cubierta (39,7%).<br/><br/>Hitos: cierre de las clínicas UNTREF el 10 de octubre (entre 500 y 700 adolescentes; taekwondo, vóley, fútbol e IA) y cierre del Programa el 7 de noviembre (14 de noviembre como fecha alternativa en caso de suspensión).<br/><br/>Desafío 2027: ampliar la capacidad del Programa y fortalecer la participación sostenida.<br/><br/><span style=\"font-size:11.5px; font-style:italic;\">Ver también: Red de articulación y Líneas de acción 2027, en Gestiones propias.</span>", "coordinador": "Patricia González Chans"}, "lazos": {"nombre": "Reconstruyendo Lazos", "brief": "Brinda herramientas que el mundo del trabajo requiere, por medio de prácticas socioeducativas laborales y distintas instancias de capacitación, para incrementar las condiciones de empleabilidad de adolescentes y jóvenes. Promueve la inserción laboral en situación de vulnerabilidad social, mediante capacitaciones y prácticas en espacios de trabajo.<br/><br/>Como marca distintiva, cuenta con un dispositivo de acompañamiento que orienta la experiencia de quienes participan. Destinatarios: adolescentes y jóvenes entre 16 y 21 años en situación de vulnerabilidad social de la Ciudad de Buenos Aires.", "tiene_organizaciones": true, "gestion": "Cada espacio de práctica es un tercero (empresa, organismo o espacio cultural, de los sectores público y privado) que recibe jóvenes en práctica laboral. El programa dura aproximadamente un año; las prácticas son de cuatro horas diarias, entre dos y cuatro días por semana, y se otorga una beca mensual a todas y todos los participantes.<br/><br/>El ingreso del adolescente o joven al Programa sigue una hoja de ruta propia — ver Gestiones propias, Hoja de ruta del programa. El circuito de alta institucional de cada espacio de práctica (la organización o empresa que lo recibe) todavía no está confirmado.", "coordinador": "Anabella Divan"}, "lideres": {"nombre": "Líderes Recreativos y Comunitarios", "brief": "Propuesta gratuita de inclusión y capacitación dirigida a adolescentes entre 16 y 18 años de la Ciudad de Buenos Aires, con el objetivo de generar espacios de formación en recreación y liderazgo comunitario que promuevan procesos de participación y autogestión en sus barrios e instituciones. Se desarrolla desde 1998.<br/><br/>El curso tiene una duración de tres años y a lo largo del trayecto se comparten salidas, campamentos y viajes. Es dictado por un equipo docente formado por profesionales de diversas áreas con una larga trayectoria en la coordinación de grupos.", "tiene_organizaciones": false, "gestion": "Funciona en sede fija propia (Escuela García Lorca, los sábados) y hace salidas esporádicas a otros lugares todavía sin detallar.", "diagnostico": "Diagnóstico 2026: en las presentaciones de Desafío 2027 este programa aparece nombrado como \"Recreación Comunitaria\" — es el mismo programa, con un alias informal usado en ese material, no un renombre oficial. El nombre oficial sigue siendo Líderes Recreativos y Comunitarios. 250 adolescentes y jóvenes entre 1er año, 2do año, 3er año y ERA. La falta de presupuesto obligó a readaptar actividades centrales del trayecto formativo y a suspender otras — se trabajó recortando recursos y readaptando propuestas, todas en espacios gratuitos.<br/><br/><b>Hitos 2026:</b><br/>• 1er año — 2 campamentos: el primero realizado en la Escuela García Lorca; el segundo, de noviembre, con lugar todavía pendiente.<br/>• 2do año — campamento readaptado y realizado en la Escuela García Lorca; gira a Mar del Plata/Mar Chiquita sin presupuesto, en proceso de readaptación.<br/>• 3er año — viaje al Tríptico de la Infancia (Rosario) sin presupuesto, en readaptación; campamento con el Programa Juegotecas suspendido por falta de presupuesto; evento \"Conexión sin WiFi\" suspendido por falta de presupuesto.<br/>• ERA — campamento readaptado para realizarse en la Escuela García Lorca; salida al Delta del Tigre suspendida por falta de presupuesto.<br/><br/>Para 2027 se trabaja una <b>Diplomatura con la UNTREF</b> (\"Promotor Integral en Recreación Comunitaria\"), certificada al finalizar el tercer año, con esta estructura: 1er año — Bases (contenidos iniciales de recreación comunitaria); 2do año — Profundización (herramientas de coordinación, planificación y trabajo grupal); 3er año — Integración (consolidación de saberes y experiencia formativa).<br/><br/>Desafío 2027: garantizar las experiencias que forman parte de la propuesta integral del programa.", "coordinador": "Romina Valsecchi"}, "coopa": {"nombre": "COOPA", "brief": "La institución trabaja con adolescentes de 14 a 21 años capacitándolos en distintos oficios (mecánica, herrería, electricidad, computación, diseño gráfico) y desarrollando también actividades recreativas, deportivas y espacios de trabajo en formación laboral, en derechos humanos y en lectura y escritura.<br/><br/><b>Objetivos generales:</b> propiciar un espacio de formación integral para el trabajo donde la formación técnica de los oficios sea a su vez disparador hacia otros conocimientos de disciplinas básicas y de desarrollo de saberes aptitudinales y actitudinales para el desenvolvimiento en el mundo del trabajo. Promover el conocimiento y ejercicio de los derechos humanos y sociales de las/os jóvenes, apuntando a fortalecer su protagonismo, toma de decisiones y reflexión-acción sobre su realidad, en la perspectiva de sujetos de derecho hacia la ciudadanía plena.<br/><br/><b>Enfoque pedagógico-didáctico:</b> la enseñanza tiene como punto de partida la realidad propia, la experiencia y su relación con la teoría y la práctica, combinando el trabajo colectivo con la articulación por áreas. La modalidad de taller/salón permite que circule de manera horizontal y democrática la palabra, construyendo el pensamiento crítico y la identidad de pertenencia.", "tiene_organizaciones": false, "gestion": "Funciona en centros propios del programa, no en organizaciones externas. Uno de esos centros (Barrio Rivadavia I) es además el que usa TABF prestado.", "coordinador": "Daniel Quiroz"}, "bajoflores": {"nombre": "TABF — Talleres Adolescentes del Bajo Flores", "brief": "El Programa Talleres para Adolescentes del Bajo Flores se constituye como una articulación de organizaciones sociales y comunitarias de la zona con el Estado, con el fin de promover espacios educativos con los y las adolescentes.", "tiene_organizaciones": true, "gestion": "No tiene sede propia: usa las instalaciones que le prestan 11 instituciones de la red (comedores, capillas, radio comunitaria, biblioteca, club, escuela y una sede de COOPA).", "coordinador": "Lorena Fernández"}, "turismo": {"nombre": "Turismo Social", "brief": "Sin reseña oficial disponible todavía. Actualmente con poca actividad, según lo indicado.", "tiene_organizaciones": false, "gestion": "Tiene sede propia (Parque Sarmiento, según la nómina de personal), todavía no incorporada a la base a la espera de confirmación. En las presentaciones de Desafío 2027 aparece nombrado como \"Turismo Recreativo\" — es el mismo programa; el nombre oficial sigue siendo Turismo Social.", "coordinador": "Alejandro Agazzi"}};
const MAPA_GESTIONES_PROGRAMA = {"adolescencias": [{"titulo": "Sistema de control: de la Coordinadora al equipo territorial", "desc": "Tres niveles de conducción técnica del Programa.", "sub": [{"titulo": "Coordinadora del Programa — Patricia González Chans", "desc": "Responsable de la coordinación de los equipos técnicos y del monitoreo de la generación y disponibilidad de los recursos necesarios para el adecuado funcionamiento del equipo y el desarrollo del Programa."}, {"titulo": "Sub Coordinación", "desc": "Nivel intermedio entre la Coordinadora del Programa y los equipos territoriales. Son cinco personas, cada una a cargo de un equipo. Planifican, guían y controlan las actividades que se desarrollan a lo largo del año, y reportan a la Coordinadora del Programa. El detalle de cada Sub Coordinación y su equipo está en Equipo — Sub Coordinaciones, más abajo."}, {"titulo": "Equipo territorial — talleristas y operadoras/es sociales", "desc": "Dictan los talleres y acompañan a las y los adolescentes en el territorio. Responden a la Sub Coordinación. Si bien integran el Programa, pertenecen formalmente a la organización conveniada, no a la planta del equipo técnico de la Gerencia."}]}, {"titulo": "Equipo — Sub Coordinaciones de supervisión", "desc": "Cinco Sub Coordinaciones, cada una con su propio equipo. Reportan directamente a la Coordinadora del Programa.", "sub": [{"titulo": "Sub Coordinación — Analía Mauvezin", "desc": "Equipo: Nahuel Bernardez, Noelia Miceli, Laura Santambrogio, Sonia Inés Padro, Javier Lazarte."}, {"titulo": "Sub Coordinación — Analía Dillman", "desc": "Equipo: Damián Rico, Gonzalo Sarrais, Omar Mendoza, Mariana Cruz, Vacante, Vacante."}, {"titulo": "Sub Coordinación — Sofía Zukerfeld", "desc": "Equipo: Elisa Ordiozola, Analía Maldones, Silvina Sanseverino, Andrea Giussanni, Diego Couzo, Vacante."}, {"titulo": "Sub Coordinación — Carla Chapato", "desc": "Equipo: Marcela Avezzano, Carolina Vazquez, Celeste Farbman (licencia por maternidad), Silvina Alonso (licencia por maternidad), Vacante, Vacante."}, {"titulo": "Sub Coordinación — M. Eugenia García", "desc": "Equipo: Cyntia Tonelli, Virginia Domínguez, Ale Rost, Elena Montaldo, Ivanna Palma, Vacante."}]}, {"titulo": "Equipo — Área Apoyo y Administrativos del Programa", "desc": "Dos grupos de personal del Programa, además de la línea de Coordinación y Sub Coordinación.", "sub": [{"titulo": "Área Apoyo", "desc": "María del Mar Pardoa Puigdomenech, Roberto Osvaldo Fabbricatore, Melisa Mónica Marino, Federico Pereyra."}, {"titulo": "Administrativos", "desc": "Víctor González, Vacante, Vacante."}]}, {"titulo": "Circuito de documentación y convenios", "desc": "Mediados de febrero: Pablo Riveli envía a las organizaciones el listado completo de la documentación necesaria para renovar el convenio.<br/><br/>Las organizaciones presentan la documentación — gran parte debe renovarse o actualizarse cada año. El tiempo de entrega depende de cada una; se estima en hasta 15 días.<br/><br/>Primeros días de marzo: el Programa envía el presupuesto a las organizaciones y les solicita el proyecto anual y la fecha de inicio de las actividades, que luego se informa a las y los adolescentes en la confirmación de vacantes.<br/><br/>El Programa recibe y evalúa los proyectos presentados.<br/><br/>Los proyectos evaluados se envían a Pablo Riveli para integrarlos al legajo de cada organización.<br/><br/>Con la documentación completa y el proyecto evaluado, la organización queda en condiciones de firmar el convenio — hacia mediados de marzo, si no hay inconvenientes.<br/><br/><span style=\"font-size:11.5px; font-style:italic;\">Complementa, con el detalle específico de este programa, el circuito general de Convenios y organizaciones de la Gerencia.</span>"}, {"titulo": "Circuito de supervisión e informes", "desc": "Cada integrante del equipo de supervisión tiene asignados aproximadamente 12 talleres, en dos instituciones y, como máximo, tres. La frecuencia de visita es semanal por institución y quincenal por taller, alternando las actividades visitadas.<br/><br/>La asistencia de las y los adolescentes la registran operadores/as sociales o referentes institucionales. Hoy está repartida entre el sistema (instituciones que ya cuentan con VPN y capacitación) y planillas Excel (el resto, hasta completar ese proceso) — ver Accesos VPN, en los trámites de la Gerencia.<br/><br/>En cada visita se registra además la cantidad de participantes y se realiza una evaluación cualitativa: dinámica y participación grupal e individual, vínculo de operadores/as y docentes con las y los adolescentes, propuesta pedagógica, seguimientos sociales y capacidad de la coordinación institucional.<br/><br/>Cada visita genera un informe de supervisión. Además hay tres informes periódicos al año: fines de julio, fines de octubre, y entre el 15 y el 20 de diciembre (al cierre del convenio). Se reúnen en una carpeta de Drive de la Gerencia y el Programa; el formato común todavía está en construcción.<br/><br/>Cuando una situación requiere la intervención del Consejo de los Derechos de Niñas, Niños y Adolescentes u otro efector, se articula entre los equipos: reuniones, intercambio de información e informes, derivaciones y acuerdos de intervención — ver también Derivación al Consejo de Derechos, más abajo, para el circuito formal con expediente."}, {"titulo": "Circuito de inscripciones", "desc": "El circuito comienza con dos procesos en paralelo: la evaluación del índice de vulnerabilidad y el acondicionamiento del sistema, en articulación con GODI (Gerencia Operativa de Desarrollo Informático del GCBA), y la construcción de la oferta de actividades junto con las instituciones.<br/><br/>Primeros días de diciembre: las instituciones presentan la oferta acordada, que se carga y controla en el sistema.<br/><br/>Desde el 2 de enero y durante enero y febrero: preinscripción abierta — requiere el sistema acondicionado; en algunos años las dificultades del sistema obligaron a reducir el período.<br/><br/>Del 1 al 15 de marzo: procesamiento de datos y ranking por índice de vulnerabilidad.<br/><br/>Desde el 15 de marzo: confirmación de vacantes, que requiere las fechas de inicio informadas por las organizaciones — este punto suele estar condicionado por la definición y aceptación del presupuesto.<br/><br/>Existe una base de datos por organización, actividad/disciplina y edad, que lleva Bernardo."}, {"titulo": "Circuito de pagos", "desc": "", "sub": [{"titulo": "A las y los adolescentes (becas)", "desc": "Las adolescencias reciben este estímulo económico con el fin de garantizar la equidad material, incentivar la permanencia en los espacios de contención y eliminar las barreras socioeconómicas que dificultan su desarrollo pleno. La beca funciona como una herramienta de política pública destinada a asegurar que las y los jóvenes en situación de vulnerabilidad social puedan afrontar los viáticos, materiales y necesidades básicas asociadas a su participación en actividades educativas, culturales, tecnológicas o deportivas. De esta forma, el Estado promueve la autonomía, la inclusión y la restitución de derechos vulnerados.<br/><br/><b>Marco normativo regulatorio</b> — la entrega de estos fondos obligatorios se sustenta en tres niveles jurídicos:<br/>• <b>Tratados internacionales:</b> la Convención sobre los Derechos del Niño (con rango constitucional en Argentina), que obliga al Estado a disponer del \"máximo de los recursos disponibles\" para asegurar el desarrollo integral de las infancias y adolescencias.<br/>• <b>Leyes de protección integral:</b> Ley Nacional N° 26.061 (los niños, niñas y adolescentes son sujetos de derecho; mandata al Estado a implementar políticas activas frente a la exclusión social) y Ley N° 114 de la Ciudad de Buenos Aires (obliga al GCBA a aplicar programas públicos que garanticen el goce de derechos en condiciones de igualdad, dignidad y sin discriminación).<br/>• <b>Normativa de ejecución específica:</b> decretos porteños (Decreto N° 428/07 y resoluciones del Ministerio de Desarrollo Humano y Hábitat), que autorizan las partidas presupuestarias específicas y definen legalmente el beneficio como un estímulo nominal no remunerativo.<br/><br/><b>Circuito operativo — Programa Adolescencias</b><br/><br/>La inscripción es abierta, libre y gratuita, a través del sistema del Gobierno de la Ciudad.<br/><br/>Una vez cargadas todas las inscripciones, se realiza un proceso de selección que prioriza a las adolescencias con mayor situación de marginalidad y problemática social a la hora de asignar vacante. El programa cuenta con aproximadamente 7.000 vacantes.<br/><br/>Las y los seleccionados se registran en el <b>RIB</b> (sistema interno del Gobierno de la Ciudad), donde el personal administrativo carga los datos de identificación y contacto del adolescente (CUIT, dirección, teléfono, nombre completo, DNI, CUIL) y, cuando corresponde, los mismos datos de su representante.<br/><br/>Los y las adolescentes mayores de 13 años pueden cobrar la beca ellos mismos, mediante un CBU del Banco Ciudad, o a través de un representante legal (tutor/a). Los y las menores de 13 años requieren representante.<br/><br/>Con la información cargada en el RIB, la carga del pago en sí se realiza en el <b>PSOC</b>, otro sistema interno del Gobierno de la Ciudad. Ambos sistemas (RIB y PSOC) dan aviso a Tesorería, que habilita la acreditación del pago."}, {"titulo": "A las organizaciones", "desc": "Durante 2025 y 2026 la modalidad vigente es el pago a cupo total: el cupo de vacantes de cada categoría establecida en el convenio, multiplicado por el valor correspondiente a cada categoría. El equipo del Programa no genera mensualmente un nuevo cálculo o reporte; el proceso tiene varias fases manuales a cargo de la Dirección General: recepción de la copia de la factura mensual, elaboración de la rendición, armado del informe anexo con los montos a pagar, elevación a la firma de la Directora General, y armado de cada disposición de pago por organización.<br/><br/>Una vez determinado el monto, se ejecuta el pago y la organización recibe un número de DGT junto con la solicitud de facturación. La organización emite la factura, la carga en el sistema con ese número de DGT y la envía al área contable de la Dirección General, que completa la instancia para la transferencia.<br/><br/>Información pendiente de incorporar, según el propio diagnóstico del Programa: los montos efectivamente pagados por organización y el promedio por ONG."}]}, {"titulo": "Convenio con UNTREF — clínicas deportivas", "desc": "Consentimiento informado a padres, cronograma, brief por clínica/institución, ejecución, síntesis de participación y cierre."}, {"titulo": "Red de articulación", "desc": "", "sub": [{"titulo": "UNTREF", "desc": "Proyectos presentados, clínicas y cierre del Programa."}, {"titulo": "UBA", "desc": "Articulación institucional."}, {"titulo": "Banco Ciudad", "desc": "Articulación institucional."}, {"titulo": "Clubes (San Lorenzo, Racing, Argentinos Juniors)", "desc": "Alianza deportiva."}, {"titulo": "Radio Mitre", "desc": "Articulación y comunicación."}]}, {"titulo": "Por expediente (ingreso excepcional)", "desc": "Ingresa por expediente SADE. Se baja el formulario de ingreso (informe gráfico), se pasa a la coordinadora del programa por mail, se carga en un cuadro compartido (contacto con el adolescente, actividad elegida). Se arman los eleves que firma la Gerencia Operativa Legal, se vinculan al expediente y se remite al destinatario que lo envió."}, {"titulo": "Por oficio (pedidos 104 y requerimientos)", "desc": "La Dirección deriva el oficio al programa correspondiente con plazo previo al vencimiento. El programa arma la información, se valida que sea coherente con lo pedido, y se responde por GEDO firmado por la Gerencia Operativa Legal, revisado antes por la abogada de la Dirección General."}, {"titulo": "Derivación al Consejo de Derechos (vulneración de derechos)", "desc": "Ante una vulneración de derechos de un/a adolescente, el programa correspondiente eleva un informe social con los datos completos del adolescente y sus referentes, describiendo la situación que acredita la vulneración.<br/><br/>Se solicita a Mesa de Entradas de la DGPINA la carátula de expediente electrónico. El código de trata tiene dos referencias distintas, según la fuente:<br/>• <b>MDSG0703A</b> — según el mail de la abogada de la Dirección General.<br/>• <b>AJG00101A</b> (\"o similar\") — según el documento interno de circuitos de la Gerencia.<br/><br/>Se vinculan al expediente el informe social y los informes técnicos completos, firmados. El expediente pasa al usuario de Mesa de Entradas y se eleva desde la Gerencia Operativa Legal, dirigido a la Dirección General, que deriva a DGPDES o directamente al Consejo de Derechos de Niñas, Niños y Adolescentes."}, {"titulo": "Líneas de acción 2027", "desc": "Cuatro líneas concretas para pasar de alianzas institucionales a experiencias y oportunidades para los adolescentes.", "sub": [{"titulo": "Adolescencia Te Prepara", "desc": "Primer empleo, educación financiera, orientación vocacional, mentorías, visitas a empresas."}, {"titulo": "Adolescencia Crea", "desc": "Inteligencia artificial, programación, audiovisual, podcast, comunicación, Hackatón Adolescencia."}, {"titulo": "Adolescencia Saludable", "desc": "Nutrición, deporte, hábitos saludables, primeros auxilios, prevención."}, {"titulo": "Adolescencia Conecta", "desc": "Universidades, empresas, medios, clubes profesionales, producción audiovisual, referentes."}]}], "lazos": [{"titulo": "Hoja de ruta del programa", "desc": "El ingreso y recorrido de cada adolescente o joven en el Programa sigue estas etapas, en orden.", "sub": [{"titulo": "Inscripción / derivación", "desc": "Punto de entrada al Programa."}, {"titulo": "Talleres de ingreso", "desc": "Ocho encuentros. Incluyen contenidos sobre el mundo del trabajo y herramientas de búsqueda laboral — ver Taller de Ingreso — contenidos, más abajo."}, {"titulo": "Entrevista de ingreso", "desc": "Espacio individual con un/a operador/a social, luego de los ocho encuentros del Taller de Ingreso, para evacuar dudas sobre el Programa, conocer intereses, recorridos educativos y experiencias previas vinculadas al mundo del empleo, y disponibilidad horaria, y así definir cómo continúa el camino de cada adolescente o joven en el Programa."}, {"titulo": "Prácticas laborales", "desc": "Prácticas socioeducativas laborales en espacios de trabajo de organizaciones de los sectores público y privado."}, {"titulo": "Tutorías", "desc": "Acompañamiento continuo a cargo del/la operador/a social asignado/a, en paralelo a la práctica — ver Operador/a Social — rol en este programa, más abajo."}, {"titulo": "Egreso y entrega de diploma", "desc": "Cierre del recorrido en el Programa."}]}, {"titulo": "Operador/a Social — rol en este programa", "desc": "Acompaña el proceso de aprendizaje de cada adolescente o joven a través de las prácticas y las tutorías. Establece los acuerdos de su recorrido mediante encuentros de seguimiento en la oficina (entrevistas) y comunicaciones permanentes, para ver cómo le está yendo, qué dificultades o dudas presenta respecto de las tareas, cómo siente el vínculo con el referente de prácticas, y evacuar preguntas sobre cuestiones administrativas.<br/><br/>En este programa, los/as operadores/as sociales son profesionales. Esto es distinto a cómo se conforma ese mismo rol en Programa Adolescencias, donde las operadoras y operadores sociales son elegidos por la organización conveniada y, en general, no tienen título: son militantes de las organizaciones, con trayectoria de ayuda social."}, {"titulo": "Taller de Ingreso — contenidos", "desc": "Ocho encuentros, previos a la entrevista de ingreso.", "sub": [{"titulo": "Armado de CV", "desc": "Información personal, objetivo laboral, educación, educación complementaria y experiencia laboral, con pautas concretas de redacción y orden cronológico inverso."}, {"titulo": "Definiciones del mundo del trabajo", "desc": "Qué es una práctica educativa laboral, qué es un/a Operador/a Social, y definiciones de trabajo y empleo (relación de dependencia, autónomo, eventual/temporal, voluntario, pasantía)."}, {"titulo": "Recursos para la búsqueda laboral", "desc": "Portales de empleo del GCBA y otros organismos, sindicatos, ONG's, organizaciones barriales, comunitarias y universitarias."}]}, {"titulo": "Pago de becas", "desc": "Las adolescencias cobran este estímulo económico con el fin de garantizar la equidad material, incentivar la permanencia en los espacios de contención y eliminar las barreras socioeconómicas que dificultan su desarrollo pleno.<br/><br/>La beca no funciona como un salario ni como un subsidio discrecional, sino como una herramienta de política pública para asegurar que los jóvenes en situación de vulnerabilidad social puedan costear los viáticos, materiales y necesidades básicas asociadas a su participación en actividades educativas, culturales, tecnológicas o deportivas. De esta forma, el Estado promueve la autonomía, la inclusión y la restitución de derechos vulnerados.<br/><br/><b>Marco normativo regulatorio</b> — la entrega de estos fondos obligatorios se sustenta en tres niveles jurídicos:<br/>• <b>Tratados internacionales:</b> la Convención sobre los Derechos del Niño (con rango constitucional en Argentina), que obliga al Estado a disponer del \"máximo de los recursos disponibles\" para asegurar el desarrollo integral de las infancias y adolescencias.<br/>• <b>Leyes de protección integral:</b> Ley Nacional N° 26.061 (los niños, niñas y adolescentes son sujetos de derecho; mandata al Estado a implementar políticas activas frente a la exclusión social) y Ley N° 114 de la Ciudad de Buenos Aires (obliga al GCBA a aplicar programas públicos que garanticen el goce de derechos en condiciones de igualdad, dignidad y sin discriminación).<br/>• <b>Normativa de ejecución específica:</b> decretos porteños (Decreto N° 428/07 y resoluciones del Ministerio de Desarrollo Humano y Hábitat), que autorizan las partidas presupuestarias específicas y definen legalmente el beneficio como un estímulo nominal no remunerativo.<br/><br/><b>Circuito operativo:</b> Un/a adolescente elegible genera expediente, se cruza contra su cuenta bancaria, cambia de estado (elegibilidad, operativa, baja solicitada) y se procesa el pago mensual.<br/><br/><b>Cobro de la beca — del lado del participante</b><br/><br/>Una vez tramitado el pago, se informa al adolescente o joven —o, si corresponde, al referente que designó en su inscripción al Programa— cuándo retirar la tarjeta del Programa en el banco.<br/><br/>El retiro se hace en la sede Nueva Pompeya del Banco Ciudad (Av. Del Barco Centenera 2906), de 10h a 15h, el día que corresponde según el último dígito del DNI del titular: 0 y 1, lunes; 2 y 3, martes; 4 y 5, miércoles; 6 y 7, jueves; 8 y 9, viernes. Se presenta el DNI original y una fotocopia del titular.<br/><br/>Con la tarjeta ya en mano, se puede solicitar la clave PIN a través del centro de atención telefónica del banco, lo que habilita a operar en cajero automático.<br/><br/>La tarjeta funciona como tarjeta de débito para realizar compras. Por cajero automático solo pueden hacerse extracciones — no consultas de saldo."}], "lideres": [{"titulo": "Insumos para campamentos", "desc": "Por cada campamento programado: pedido de insumos, compra, depósito y entrega."}, {"titulo": "Alianza con Radio Mitre", "desc": "A partir del taller de radio del programa, los y las jóvenes participan de la organización y producción de la propuesta \"Voces que Inspiran\", en articulación con Radio Mitre."}, {"titulo": "Hitos 2026", "desc": "Readaptaciones y suspensiones por falta de presupuesto, por cohorte.", "sub": [{"titulo": "1er año", "desc": "2 campamentos: el primero realizado en la Escuela García Lorca; el segundo, de noviembre, con lugar todavía pendiente."}, {"titulo": "2do año", "desc": "Campamento readaptado y realizado en la Escuela García Lorca. Gira a Mar del Plata/Mar Chiquita sin presupuesto, en proceso de readaptación."}, {"titulo": "3er año", "desc": "Viaje al Tríptico de la Infancia (Rosario) sin presupuesto, en readaptación. Campamento con el Programa Juegotecas suspendido por falta de presupuesto. Evento \"Conexión sin WiFi\" suspendido por falta de presupuesto."}, {"titulo": "ERA", "desc": "Campamento readaptado para realizarse en la Escuela García Lorca. Salida al Delta del Tigre suspendida por falta de presupuesto."}]}], "coopa": [], "bajoflores": [], "turismo": []};
const MAPA_GESTIONES_GENERALES = [{"id": "conv", "titulo": "Convenios y organizaciones", "desc": "La articulación con las organizaciones sociales se concreta a través de un Convenio. El ingreso de la propuesta se genera a través de un expediente, donde se envía a la DGTAL para la conformación del marco jurídico correspondiente. Posteriormente se remite a la firma del Ministerio de Desarrollo Humano y Hábitat (MDHyH). Una vez firmado, se procede al pago.<br/><br/><b>¿Por qué se trabaja con organizaciones sociales?</b><br/><br/><b>Democracia participativa y cogestión.</b> La Constitución de la CABA establece que la democracia de la Ciudad tiene carácter participativo. Los considerandos de los convenios recuperan este mandato: incorporar a las OSC permite un diseño de políticas públicas más democrático, plural y cercano a las necesidades reales del vecino.<br/><br/><b>Capilaridad territorial y especialización técnica.</b> Las organizaciones sociales poseen un \"saber hacer\" y un arraigo territorial que el aparato estatal no siempre logra de forma inmediata. El Estado firma convenios para potenciar y articular esas capacidades técnicas, descentralizando la ejecución de programas para llegar de forma más rápida y empática a la población vulnerable.<br/><br/><b>Corresponsabilidad en la protección de derechos.</b> En niñez y adolescencia (ámbito de la DGPINA), la Ley N.° 114 derriba el viejo modelo de patronato e instaura el principio de corresponsabilidad: la protección integral de derechos no es tarea exclusiva del sector público, sino una responsabilidad compartida entre el Estado, las familias y las organizaciones de la comunidad.<br/><br/><b>Marco jurídico estructurado</b><br/><pre class=\"mono\" style=\"font-size:11px; line-height:1.4; white-space:pre; overflow-x:auto; background:#fff; border-radius:6px; padding:10px; color:var(--ink);\">┌─────────────────────────────────────────┐\n│          Constitución de la CABA        │\n│   (Arts. 11, 32 y 39 - Participación)   │\n└────────────────────┬────────────────────┘\n                     ▼\n┌─────────────────────────────────────────┐\n│        Leyes de Fondo (CABA)            │\n│  - Ley N.° 114 (Protección Integral)    │\n│  - Ley N.° 6.684 (Ley de Ministerios)   │\n└────────────────────┬────────────────────┘\n                     ▼\n┌─────────────────────────────────────────┐\n│         Decretos y Resoluciones         │\n│  - Decreto N.° 1360/07 (Convenio Marco) │\n│  - Res. N.° 97/SECLYT/25 (Circuito)     │\n└─────────────────────────────────────────┘</pre><br/><b>Nivel constitucional:</b> la Constitución de la CABA obliga al Estado a garantizar canales de participación ciudadana y a fomentar las actividades de las entidades comunitarias sin fines de lucro.<br/><br/><b>Nivel legal de competencia:</b> la Ley N.° 6.684 encomienda al Ministerio de Desarrollo Humano y Hábitat la articulación de sus políticas con actores privados y del tercer sector. La Ley N.° 114 da el marco protectorio específico para que la DGPINA delegue o complemente la atención de adolescentes mediante estos instrumentos institucionales.<br/><br/><b>Nivel operativo y procedimental:</b> el Decreto N.° 1360/07 unifica las reglas mediante el \"Modelo de Convenio Marco de Cooperación\", resguardando la autonomía jurídica y técnica de la organización frente al Estado. La Resolución N.° 97/SECLYT/25 garantiza la transparencia del circuito digital, exigiendo dictámenes legales antes de que los fondos públicos sean girados.<br/><br/><span style=\"font-size:11px; color:var(--ink-soft);\">Fuentes: Constitución de la CABA · Ley N.° 114 · Ley N.° 6.684 · Decreto N.° 1360/07 · Resolución N.° 97/SECLYT/25 · documentosboletinoficial.buenosaires.gob.ar · mpfciudad.gob.ar</span<br/><br/><b>Marco jurídico estructurado</b><br/><pre class=\"mono\" style=\"font-size:11px; line-height:1.4; white-space:pre; overflow-x:auto; background:#fff; border-radius:6px; padding:10px; color:var(--ink);\">┌─────────────────────────────────────────┐\n│          Constitución de la CABA        │\n│   (Arts. 11, 32 y 39 - Participación)   │\n└────────────────────┬────────────────────┘\n                     ▼\n┌─────────────────────────────────────────┐\n│        Leyes de Fondo (CABA)            │\n│  - Ley N.° 114 (Protección Integral)    │\n│  - Ley N.° 6.684 (Ley de Ministerios)   │\n└────────────────────┬────────────────────┘\n                     ▼\n┌─────────────────────────────────────────┐\n│         Decretos y Resoluciones         │\n│  - Decreto N.° 1360/07 (Convenio Marco) │\n│  - Res. N.° 97/SECLYT/25 (Circuito)     │\n└─────────────────────────────────────────┘</pre><br/><b>Nivel constitucional:</b> la Constitución de la CABA obliga al Estado a garantizar canales de participación ciudadana y a fomentar las actividades de las entidades comunitarias sin fines de lucro.<br/><br/><b>Nivel legal de competencia:</b> la Ley N.° 6.684 encomienda al Ministerio de Desarrollo Humano y Hábitat la articulación de sus políticas con actores privados y del tercer sector. La Ley N.° 114 da el marco protectorio específico para que la DGPINA delegue o complemente la atención de adolescentes mediante estos instrumentos institucionales.<br/><br/><b>Nivel operativo y procedimental:</b> el Decreto N.° 1360/07 unifica las reglas mediante el \"Modelo de Convenio Marco de Cooperación\", resguardando la autonomía jurídica y técnica de la organización frente al Estado. La Resolución N.° 97/SECLYT/25 garantiza la transparencia del circuito digital, exigiendo dictámenes legales antes de que los fondos públicos sean girados.<br/><br/><span style=\"font-size:11px; color:var(--ink-soft);\">Fuentes: Constitución de la CABA · Ley N.° 114 · Ley N.° 6.684 · Decreto N.° 1360/07 · Resolución N.° 97/SECLYT/25 · documentosboletinoficial.buenosaires.gob.ar · mpfciudad.gob.ar</span>", "sub": [{"titulo": "Democracia participativa y cogestión", "desc": "La Constitución de la CABA establece que la democracia de la Ciudad tiene carácter participativo. Los considerandos de los convenios recuperan este mandato: incorporar a las OSC permite un diseño de políticas públicas más democrático, plural y cercano a las necesidades reales del vecino."}, {"titulo": "Capilaridad territorial y especialización técnica", "desc": "Las organizaciones sociales poseen un \"saber hacer\" y un arraigo territorial que el aparato estatal no siempre logra de forma inmediata. El Estado firma convenios para potenciar y articular esas capacidades técnicas, descentralizando la ejecución de programas para llegar de forma más rápida y empática a la población vulnerable."}, {"titulo": "Corresponsabilidad en la protección de derechos", "desc": "En niñez y adolescencia (ámbito de la DGPINA), la Ley N.° 114 derriba el viejo modelo de patronato e instaura el principio de corresponsabilidad: la protección integral de derechos no es tarea exclusiva del sector público, sino una responsabilidad compartida entre el Estado, las familias y las organizaciones de la comunidad."}]}, {"id": "vpn", "titulo": "Accesos VPN", "desc": "<b>Por qué es obligatoria</b> — la VPN es el único puente técnico para acceder al Sistema de Administración de Documentos Electrónicos (SADE), canal obligatorio para tramitar expedientes, rendiciones y gestiones estatales (Decreto N° 589/09). Para los talleres y organizaciones que reciben apoyo económico, también es indispensable para acceder a los módulos de Planes Sociales y Subsidios (PSOCS) y al Registro de Identificación de Beneficiarios (RIB), exigido por la Resolución N° 557/SLYT/15 para fiscalizar y transparentar las prestaciones otorgadas por la Ciudad. La Agencia de Sistemas de Información (ASI) exige conexiones cifradas y validación nominal por CUIL para proteger los datos sensibles de los beneficiarios.", "sub": [{"titulo": "Circuito — pedido nuevo", "desc": "Programa Adolescencias envía por mail a RRHH: formulario, copia de convenio y copia de DNI → RRHH corrobora que el usuario corresponda a su cargo u oficio (control de personal), emite el ticket, y avisa a la coordinadora del Programa y a la ASI que está habilitado para continuar → la ASI deriva internamente a GODI (Gerencia Operativa de Desarrollo Informático, GCBA) → GODI habilita a cada usuario en el sistema de Carga de Asistencia y Acompañamiento del Programa Adolescencias → se entrega el acceso al Programa."}, {"titulo": "Circuito — prórroga", "desc": "Mismo ingreso por mail a RRHH (formulario, convenio, DNI) → RRHH corrobora y emite el ticket, avisa a la coordinadora y a la ASI → como el sistema ya está habilitado, la ASI extiende la vigencia 365 días más, sin derivar a GoDi → avisa al Programa, que confirma la prórroga. <span style=\"font-size:11.5px; color:var(--warn);\">⚠ Documento marcado como BORRADOR por el propio equipo: este paso de la ASI está señalado ahí mismo como inferencia, pendiente de confirmar.</span>"}]}, {"id": "log", "titulo": "Logística de actividades y comunicación", "desc": "Cada programa calendariza el mes. De cada actividad sale un Brief que documenta la actividad que se realizará, la fecha, el lugar, el horario, la cantidad de participantes, responsables y acompañantes, los micros en caso de requerir y la solicitud de comida (menú festivo, refrigerios, viandas). También se gestionan acá las solicitudes de piezas de comunicación (diplomas, folletos, afiches) por Google Form. Guadalupe Coll (RAP) hace el seguimiento de estas tres gestiones. El destino final de las solicitudes, una vez enviadas, no está documentado todavía."}, {"id": "aud", "titulo": "Auditorías", "desc": "En construcción."}, {"id": "diag", "titulo": "Diagnóstico de gestión 2026", "desc": "<b>Marzo (punto de partida):</b> presupuesto y pautas definidos con demora; inicio de talleres postergado y asignaciones a rehacer; documentación y registros descentralizados, con informalidad de información; asistencias incompletas y débil trazabilidad; equipo en proceso de reorganización.<br/><br/><b>Marzo–septiembre (respuesta de gestión):</b> acuerdo del 6% y reasignación de talleres; regularización de convenios, pagos, RIB y PSOC; ordenamiento documental y seguimiento de asistencias; clínicas deportivas, IA y mediciones antropométricas; replanificación de programas y presencia territorial.<br/><br/><b>Hoy — avances y próximos desafíos:</b> seis programas sostenidos; mayor control y trazabilidad de la información (falta mucho todavía); procesos internos más claros y ordenados; consolidar el equipo y el sistema de monitoreo; contar con presupuesto, circuitos y recursos anticipados.<br/><br/><b>Balance:</b> la Gerencia avanzó en ordenar y sostener la ejecución. El próximo salto requiere previsibilidad institucional — presupuesto oportuno, circuitos definidos y disponibilidad de recursos operativos.<br/><br/><b>Decisión 2027 por programa</b> (sostener / fortalecer / reformular), evaluada según tres preguntas: Impacto (¿a quiénes llegamos y qué oportunidades generamos?), Demanda (¿la necesidad que dio origen al programa sigue vigente?) y Gestión (¿qué debemos sostener, fortalecer o reformular?)."}];
const MAPA_INGRESO = {"expediente": {"titulo": "Por expediente (ingreso excepcional)", "desc": "Ingresa por expediente SADE. Se baja el formulario de ingreso (informe gráfico), se pasa a la coordinadora del programa por mail, se carga en un cuadro compartido (contacto con el adolescente, actividad elegida). Se arman los eleves que firma la Gerencia Operativa Legal, se vinculan al expediente y se remite al destinatario que lo envió."}, "oficio": {"titulo": "Por oficio (pedidos 104 y requerimientos)", "desc": "La Dirección deriva el oficio al programa correspondiente con plazo previo al vencimiento. El programa arma la información, se valida que sea coherente con lo pedido, y se responde por GEDO firmado por la Gerencia Operativa Legal, revisado antes por la abogada de la Dirección General."}, "derivacion": {"titulo": "Derivación al Consejo de Derechos (vulneración de derechos)", "desc": "Ante una vulneración de derechos de un/a adolescente, el programa correspondiente eleva un informe social con los datos completos del adolescente y sus referentes, describiendo la situación que acredita la vulneración.<br/><br/>Se solicita a Mesa de Entradas de la DGPINA la carátula de expediente electrónico. El código de trata tiene dos referencias distintas, según la fuente:<br/>• <b>MDSG0703A</b> — según el mail de la abogada de la Dirección General.<br/>• <b>AJG00101A</b> (\"o similar\") — según el documento interno de circuitos de la Gerencia.<br/><br/>Se vinculan al expediente el informe social y los informes técnicos completos, firmados. El expediente pasa al usuario de Mesa de Entradas y se eleva desde la Gerencia Operativa Legal, dirigido a la Dirección General, que deriva a DGPDES o directamente al Consejo de Derechos de Niñas, Niños y Adolescentes."}};
const MAPA_PROGRAMA_ORDEN = ["adolescencias", "lazos", "lideres", "coopa", "bajoflores", "turismo"];
const MAPA_REDACT = [["Luisina Jaimes", "la Gerencia Operativa Legal"], ["Ángeles Fava", "la Gerencia Operativa Legal"], ["Paloma Besada", "la abogada de la Dirección General"], ["PALOMASBESADA", "el usuario de Mesa de Entradas"], ["Guadalupe", "el equipo de la Gerencia"], ["Adriana", "el área de personal"], ["Danilo Dignani", "el equipo legal de la Gerencia"], ["Santiago Sandoná", "el equipo administrativo"], ["Ana Prado Morello", "el equipo administrativo"], ["Pablo Riveli", "la Dirección General"], ["Bernardo", "el área que procesa los datos del Programa"]];

let mapaOrgsCache = null;
let mapaOrgsLoading = false;

async function cargarMapaOrgsSinoptico(){
  if(mapaOrgsCache || mapaOrgsLoading) return;
  mapaOrgsLoading = true;
  try{
    const { data, error } = await sb.from("organizaciones")
      .select("id,nombre,nombre_alternativo,observaciones,sedes(id,nombre,direccion,barrio,comuna),convenios(numero,estado,fecha_inicio_real,fecha_fin_real),participacion_org_programa(programa_id,modalidad,tipo_actividad)")
      .order("nombre");
    if(error){ console.error("Error cargando organizaciones:", error); }
    mapaOrgsCache = error ? [] : data;
  }catch(e){
    console.error("Excepción cargando organizaciones:", e);
    mapaOrgsCache = [];
  }finally{
    mapaOrgsLoading = false;
  }
  renderRoot();
  // una vez que el DOM ya tiene los <span id="orgs-...">, los completamos sin rehacer todo el render
  rellenarOrgsSinoptico();
}

function rellenarOrgsSinoptico(){
  const orgs = mapaOrgsCache || [];
  const porPrograma = {};
  orgs.forEach(o => (o.participacion_org_programa||[]).forEach(pp => {
    (porPrograma[pp.programa_id] = porPrograma[pp.programa_id] || []).push(o.nombre);
  }));
  MAPA_PROGRAMA_ORDEN.forEach(pid => {
    const el = document.getElementById('orgs-'+pid);
    if(!el) return;
    el.innerHTML = (porPrograma[pid] && porPrograma[pid].length) ? porPrograma[pid].sort().join(' · ') : '<span class="falta">Sin organizaciones/lugares cargados todavía.</span>';
  });
}

function mapaRedactar(texto){
  let t = texto;
  MAPA_REDACT.forEach(([nombre, reemplazo]) => { t = t.split(nombre).join(reemplazo); });
  return t;
}

function mapaLimpiarHtml(s){
  return s.replace(/<pre[^>]*>/g, "\n").replace(/<\/pre>/g, "")
          .replace(/<br\/?>/g, " ").replace(/<b>|<\/b>/g, "")
          .replace(/<i>|<\/i>/g, "").replace(/<span[^>]*>/g, "").replace(/<\/span>/g, "")
          .replace(/•/g, "-");
}

function descargarInformeMapa(){
  const orgs = mapaOrgsCache || [];

  let body = [];
  body.push(`<h1>Mapa de funcionamiento — Gerencia Operativa GOPIA</h1>`);

  body.push(`<h2>1. Gerencia Operativa</h2>`);
  body.push(`<p>La Gerencia Operativa se conforma con el equipo que la lleva adelante y con cada uno de los seis programas.</p>`);
  body.push(`<h3>Equipo</h3>`);
  MAPA_TEAM.forEach(t => {
    body.push(`<p><b>${t.nombre}</b> — <i>${t.rol}</i><br/>${t.resp}</p>`);
  });

  body.push(`<h2>2. Programas — cómo se conforma la Gerencia</h2>`);
  MAPA_PROGRAMA_ORDEN.forEach(id => {
    const p = MAPA_PROGRAMAS[id];
    const gestiones = MAPA_GESTIONES_PROGRAMA[id] || [];
    body.push(`<h3>${p.nombre}</h3>`);
    body.push(`<p><b>Coordinador/a:</b> ${p.coordinador || "sin confirmar"}</p>`);
    body.push(`<p>${p.brief}</p>`);
    body.push(`<p><b>Cómo se gestiona:</b> ${p.gestion}</p>`);
    if(p.diagnostico){ body.push(`<p><b>Diagnóstico 2026 y desafío 2027:</b> ${p.diagnostico}</p>`); }
    if(gestiones.length){
      body.push(`<p><b>Gestiones propias de este programa:</b></p><ul>`);
      gestiones.forEach(g => body.push(`<li><b>${g.titulo}:</b> ${g.desc}</li>`));
      body.push(`</ul>`);
    }
    const filtradas = orgs.filter(o => (o.participacion_org_programa||[]).some(pp => pp.programa_id === id));
    if(filtradas.length){
      body.push(`<p><b>${p.tiene_organizaciones ? "Organizaciones" : "Lugares"}:</b></p><ul>`);
      filtradas.forEach(o => {
        const conv = (o.convenios||[])[0];
        const convTxt = conv ? ("convenio " + (conv.numero||"s/n") + (conv.fecha_inicio_real ? ", vigencia desde " + conv.fecha_inicio_real : "")) : "sin convenio cargado";
        body.push(`<li>${o.nombre} (${convTxt})</li>`);
      });
      body.push(`</ul>`);
    }
  });

  body.push(`<h2>3. Trámites y gestiones administrativas de la Gerencia</h2>`);
  body.push(`<p><i>Cuestiones de forma — trámites que la Gerencia gestiona, por fuera de la estructura principal de equipo y programas.</i></p>`);
  MAPA_GESTIONES_GENERALES.forEach(g => {
    body.push(`<h3>${g.titulo}</h3>`);
    body.push(`<p>${g.desc}</p>`);
  });

  const htmlDoc = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40">
<head><meta charset="utf-8"><title>Informe GOPIA</title>
<style>
  body{font-family:Calibri,Arial,sans-serif; font-size:11pt; color:#22262B;}
  h1{font-size:20pt; color:#2D5F5A;}
  h2{font-size:15pt; color:#2D5F5A; margin-top:24pt; border-bottom:1pt solid #2D5F5A; padding-bottom:4pt;}
  h3{font-size:12.5pt; color:#22262B; margin-top:14pt;}
  p{line-height:1.4;}
  ul{margin-top:4pt;}
  li{margin-bottom:4pt;}
</style></head>
<body>${body.join("\n")}</body></html>`;

  const blob = new Blob(['\ufeff', htmlDoc], {type:"application/msword"});
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = "Informe_GOPIA.doc";
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function renderNodoGestion(g, claseTitulo){
  const bloque = `${g.desc ? `<div class="contenido"><p>${g.desc}</p></div>` : ""}`
    + (g.sub && g.sub.length ? `<ul class="rama">${g.sub.map(s => `<li><span class="titulo-l3">${s.titulo}</span><div class="contenido"><p>${s.desc}</p></div></li>`).join('')}</ul>` : "");
  return `<li><span class="${claseTitulo}">${g.titulo}</span>${bloque}</li>`;
}

function recargarMapaOrgs(){ mapaOrgsCache = null; mapaOrgsLoading = false; renderRoot(); }

function renderMapa(){
  if(!mapaOrgsCache) cargarMapaOrgsSinoptico();
  else setTimeout(rellenarOrgsSinoptico, 0);

  let out = `<button class="report-btn" onclick="descargarInformeMapa()">⬇ Descargar informe completo (Word)</button>`;
  out += `<button class="navbtn" style="width:auto; padding:0 12px; font-size:12px; font-weight:600; margin-bottom:14px;" onclick="recargarMapaOrgs()">↻ Recargar organizaciones</button>`;
  out += `<ul class="sinoptico nivel1">`;

  out += `<li>
    <span class="titulo-l1">Gerencia Operativa — GOPIA</span>
    <div class="contenido">
      <p>Se conforma con este equipo y con cada uno de los seis programas.</p>
      <div class="team-grid-sin">
        ${MAPA_TEAM.map(t => `<div class="team-item-sin"><b>${t.nombre}</b><div class="rol-sin">${t.rol}</div>${t.resp}</div>`).join('')}
      </div>
    </div>
  </li>`;

  out += `<li>
    <span class="titulo-l1">Programas</span>
    <ul class="rama">
      ${MAPA_PROGRAMA_ORDEN.map(pid => {
        const p = MAPA_PROGRAMAS[pid];
        const gestiones = MAPA_GESTIONES_PROGRAMA[pid] || [];
        let sub = `<span class="titulo-l2">${p.nombre}</span><ul class="rama">`;

        sub += `<li><span class="titulo-l3">Qué es</span><div class="contenido">
          <p class="coord">Coordinador/a: ${p.coordinador || 'falta cargar'}</p>
          <p>${p.brief}</p>
        </div></li>`;

        sub += `<li><span class="titulo-l3">Cómo se gestiona</span><div class="contenido"><p>${p.gestion}</p></div></li>`;

        if(p.diagnostico){
          sub += `<li><span class="titulo-l3">Diagnóstico 2026 y desafío 2027</span><div class="contenido"><p>${p.diagnostico}</p></div></li>`;
        }

        if(gestiones.length){
          sub += `<li><span class="titulo-l3">Gestiones propias</span><ul class="rama">
            ${gestiones.map(g => renderNodoGestion(g, "titulo-l3")).join('')}
          </ul></li>`;
        }

        sub += `<li><span class="titulo-l3">${p.tiene_organizaciones ? 'Organizaciones' : 'Lugares'}</span><div class="contenido"><p class="org-line-sin" id="orgs-${pid}">cargando…</p></div></li>`;

        sub += `</ul>`;
        return `<li>${sub}</li>`;
      }).join('')}
    </ul>
  </li>`;

  out += `<li>
    <span class="titulo-l1 orbital-sin">Trámites y gestiones administrativas de la Gerencia</span>
    <ul class="rama">
      ${MAPA_GESTIONES_GENERALES.map(g => renderNodoGestion(g, "titulo-l2 orbital-sin")).join('')}
    </ul>
  </li>`;

  out += `</ul>`;
  return out;
}
